// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;
    function setUp() public { c = new airdrop(); }

    // We fuzz the array length and contents via bytes32 seed and an arbitrary uint to vary values.
    // The distinguishing behavior is that the reference never reverts for any non-empty _tos,
    // while the mutant with i<=_tos.length can revert by reading one past the end.
    function testFuzz_property(bytes32 seed, uint256 v) public {
        // Build a non-empty address[] based on the fuzzed seed so fuzzer can explore lengths >=1.
        // Keep domain wide: allow lengths from 1 up to 8.
        uint8 len = uint8(uint256(keccak256(abi.encodePacked(seed, v))) % 8) + 1; // 1..8
        address[] memory tos = new address[](len);
        // Fill addresses deterministically from seed so different elements can vary.
        for (uint i = 0; i < len; i++) {
            tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(seed, v, i)))));
        }

        // We need a callee that will accept the low-level call and return true so the reference succeeds.
        // Use a recorder that implements transferFrom(address,address,uint256) and returns true.
        Recorder rec = new Recorder();

        // Call through c.transfer and observe whether it completed (did not revert).
        bool ok;
        try c.transfer(address(0x123), address(rec), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule: for any non-empty tos, the reference contract completes (ok == true).
        // The mutant that iterates i<=_tos.length may revert for some inputs; the fuzzer should find such.
        assertTrue(ok);
    }
}

// A minimal recorder that matches the selector bytes4(keccak256("transferFrom(address,address,uint256)"))
// It simply records calls and returns true. This ensures the low-level call succeeds and does not mask an out-of-bounds revert.
contract Recorder {
    event Called(address from, address to, uint256 v);

    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        emit Called(from, to, value);
        return true;
    }
}
